'use strict';
class WorkspaceUI{
 constructor(getState,getFilters){this.getState=getState;this.getFilters=getFilters;this.panels=[...document.querySelectorAll('.map-filter-panel')];for(const panel of this.panels)panel.querySelector('summary').addEventListener('click',()=>{if(!panel.open)for(const other of this.panels)if(other!==panel)other.open=false;});for(const panel of this.panels)panel.addEventListener('toggle',()=>{if(panel.open)for(const other of this.panels)if(other!==panel)other.open=false;});document.addEventListener('pointerdown',e=>{if(!e.target.closest('.filter-overlay')&&!e.target.closest('.info-popover'))this.close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&this.panels.some(p=>p.open)){const open=this.panels.find(p=>p.open);this.close();open.querySelector('summary').focus();e.preventDefault();e.stopPropagation();}},true);for(const name of ['pointerdown','mousedown','wheel','touchstart','dblclick'])document.querySelector('.filter-overlay').addEventListener(name,e=>e.stopPropagation());document.getElementById('rules').addEventListener('input',()=>this.refresh());this.observer=new MutationObserver(()=>this.refresh());this.observer.observe(document.getElementById('status'),{childList:true,characterData:true,subtree:true});this.resize=new ResizeObserver(()=>document.getElementById('map').style.setProperty('--map-height',document.getElementById('map').clientHeight+'px'));this.resize.observe(document.getElementById('map'));const loading=document.createElement('div');loading.id='map-activity';loading.setAttribute('aria-hidden','true');loading.hidden=true;loading.innerHTML='<span class="loading-spinner"></span><span></span>';document.getElementById('map').append(loading);this.refresh();}
 close(){for(const panel of this.panels)panel.open=false;}
 open(kind){const panel=document.getElementById(kind+'-panel');this.close();panel.open=true;document.getElementById('map').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});panel.querySelector('summary').focus({preventScroll:true});}
 applied(){this.refresh();document.getElementById('weather-panel').open=false;}
 refresh(){const s=this.getState(),f=this.getFilters(),p=s?.params;if(!p)return;const pending=['lower','upper','rain0','rain1','rain2','pen1','pen2','pen3'].some(k=>Number(document.getElementById(k).value)!==p[k])||document.getElementById('sunenabled').checked!==p.sunenabled||(p.sunenabled&&Number(document.getElementById('sunmin').value)!==p.sunmin);const lowPending=document.getElementById('lowenabled').checked!==!!p.lowenabled||(document.getElementById('lowenabled').checked&&(Number(document.getElementById('lowmin').value)!==p.lowmin||Number(document.getElementById('lowmax').value)!==p.lowmax));this.pending=pending||lowPending||!!window.ComfyDays?.airQuality?.pending;document.getElementById('weather-pending').hidden=!this.pending;document.getElementById('weather-panel').querySelector('summary').classList.toggle('pending',this.pending);const parts=[`Minimum ≥${p.lowmin}°C`,`Maximum ≤${p.upper}°C`,`Rain ≤${p.rain0} mm`,...(p.sunenabled?[`Sun ≥${p.sunmin} h`]:[]),...(window.ComfyDays?.airQuality?.enabled?['AQI median ≤'+window.ComfyDays.airQuality.maximum+' · '+(window.ComfyDays.airQuality.appliedPeriod==='mean'?'2023–2025':window.ComfyDays.airQuality.appliedPeriod)]:[])];const summary=document.getElementById('map-filter-summary');summary.replaceChildren();for(const [text,kind]of [...parts.map(text=>[text,'weather']),...(f&&(f.active||f.state.population!==50000)?f.description().map(text=>[text,'city']):[])]){const chip=document.createElement('button');chip.type='button';chip.className='rule-chip';chip.textContent=text;chip.setAttribute('aria-label','Edit '+text);chip.onclick=()=>this.open(kind);summary.append(chip);}document.getElementById('map-panel').setAttribute('aria-busy',String(s.busy));const activity=document.getElementById('map-activity');activity.hidden=!s.busy;activity.lastElementChild.textContent=document.getElementById('status').textContent;document.getElementById('export').title=this.pending?'Apply weather changes before exporting':'Export this map view with the applied filters';document.getElementById('export').disabled=s.busy||this.exporting||this.pending||!!window.ComfyDays?.airQuality?.enabled&&window.ComfyDays.airQuality.filter.busy||!document.getElementById('match-score').validity.valid||!document.getElementById('match-days').validity.valid||!!f&&(!f.valid()||f.active&&!f.ready||f.state.epi&&f.epi.loading);}
}
window.WorkspaceUI=WorkspaceUI;
// Only the handle moves the readout; map gestures and controls remain independent.
function installLocationDrag(){
 const panel=document.querySelector('.detail-panel'),handle=document.getElementById('move-details'),map=document.getElementById('map'),parent=document.querySelector('.map-layout');let drag;
 const move=(left,top)=>{const m=map.getBoundingClientRect(),p=parent.getBoundingClientRect(),bar=document.querySelector('.map-highlights').getBoundingClientRect(),r=panel.getBoundingClientRect();const minX=m.left-p.left+8,maxX=Math.max(minX,m.right-p.left-r.width-8),minY=bar.bottom-p.top+8,maxY=Math.max(minY,m.bottom-p.top-r.height-8);panel.style.left=Math.max(minX,Math.min(maxX,left))+'px';panel.style.top=Math.max(minY,Math.min(maxY,top))+'px';panel.style.right='auto';panel.style.bottom='auto';};
 for(const event of ['pointerdown','mousedown','wheel','touchstart','dblclick'])panel.addEventListener(event,e=>e.stopPropagation());
 handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;const r=panel.getBoundingClientRect(),p=parent.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left-p.left,top:r.top-p.top};handle.setPointerCapture(e.pointerId);e.preventDefault();});
 handle.addEventListener('pointermove',e=>{if(drag?.id===e.pointerId)move(drag.left+e.clientX-drag.x,drag.top+e.clientY-drag.y);});
 for(const event of ['pointerup','pointercancel','lostpointercapture'])handle.addEventListener(event,()=>drag=null);
 handle.addEventListener('keydown',e=>{const delta={ArrowLeft:[-16,0],ArrowRight:[16,0],ArrowUp:[0,-16],ArrowDown:[0,16]}[e.key];if(!delta)return;const r=panel.getBoundingClientRect(),p=parent.getBoundingClientRect();move(r.left-p.left+delta[0],r.top-p.top+delta[1]);e.preventDefault();e.stopPropagation();});
 new ResizeObserver(()=>{if(panel.style.left&&panel.offsetHeight){const r=panel.getBoundingClientRect(),p=parent.getBoundingClientRect();move(r.left-p.left,r.top-p.top);}}).observe(map);
}
installLocationDrag();
new ResizeObserver(()=>{document.getElementById('map').style.setProperty('--highlight-height',document.querySelector('.map-highlights').getBoundingClientRect().height+'px');}).observe(document.querySelector('.map-highlights'));
// Reserve the actual wrapped navigation height in immersive mode.
const syncMapClearance=()=>requestAnimationFrame(()=>{const map=document.getElementById('map'),actions=document.querySelector('.map-actions'),m=map.getBoundingClientRect(),a=actions.getBoundingClientRect();map.style.setProperty('--map-bottom-clearance',(document.body.classList.contains('map-immersed')?Math.max(12,m.bottom-a.top+12):12)+'px');});
new ResizeObserver(syncMapClearance).observe(document.querySelector('.map-actions'));
new ResizeObserver(syncMapClearance).observe(document.getElementById('map'));
new MutationObserver(syncMapClearance).observe(document.body,{attributes:true,attributeFilter:['class']});
syncMapClearance();
